function countOccurrences(haystack: string, needle: string): number {
  let count = 0;
  let idx = 0;
  while (true) {
    const found: number = haystack.indexOf(needle, idx);
    if (found < 0) {
      return count;
    }
    count += 1;
    idx = found + needle.length;
  }
}

